import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '자산 담당자';
// 가정: 자산 변동현황 등록 시 초기 상태는 기안
const INITIAL_CHANGE_STATUS = '기안';

function blank(v: unknown): boolean {
  return v === undefined || v === null || String(v).trim() === '';
}

function isId(v: unknown): boolean {
  return /^[0-9]+$/.test(String(v));
}

@Controller('api/v1')
export class FnSfr02501Controller {
  @Put('/fixed-assets/:fixedAssetId')
  async updateFixedAsset2(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['fixedAssetId'];
    const data = checks.inputOf(req.body);
    if (!isId(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산 ID 형식이 올바르지 않습니다.');
    }
    const labels: Record<string, string> = {
      assetCode: '자산코드',
      assetNo: '자산번호',
      assetName: '자산명',
      assetType: '자산 유형',
      assetCategory: '자산 분류',
      location: '위치',
      managerId: '담당자',
    };
    const missing = Object.keys(labels).filter((k) => blank(data[k]));
    if (missing.length > 0) {
      throw new ApiError(
        422,
        'FIXED_ASSET_REQUIRED_FIELD_MISSING',
        '필수 입력값이 누락되었습니다: ' + missing.map((k) => labels[k]).join(', '),
      );
    }
    if (!isId(data['managerId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '담당자 형식이 올바르지 않습니다.');
    }
    const hasPhoto = !blank(data['photoAttachmentId']);
    if (hasPhoto && !isId(data['photoAttachmentId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 사진 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE fixed_asset_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '자산을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE asset_code = :assetCode AND asset_no = :assetNo AND fixed_asset_id <> CAST(:id AS bigint)',
        { assetCode: String(data['assetCode']), assetNo: String(data['assetNo']), id },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ASSET_NO_DUPLICATED', '동일 자산코드 내에 이미 존재하는 자산번호입니다.');
      }
      const manager = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:managerId AS bigint)',
        { managerId: String(data['managerId']) },
      );
      if (manager.length === 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '존재하지 않는 담당자입니다.');
      }
      if (hasPhoto) {
        const photo = await db.query(
          'SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:photoId AS bigint)',
          { photoId: String(data['photoAttachmentId']) },
        );
        if (photo.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '존재하지 않는 자산 사진 첨부파일입니다.');
        }
      }
      await db.execute(
        'UPDATE fixed_asset SET asset_code = :assetCode, asset_no = :assetNo, asset_name = :assetName, asset_type = :assetType, asset_category = :assetCategory, location = :location, manager_id = CAST(:managerId AS bigint), photo_attachment_id = CAST(:photoId AS bigint), updated_at = now() WHERE fixed_asset_id = CAST(:id AS bigint)',
        {
          assetCode: String(data['assetCode']),
          assetNo: String(data['assetNo']),
          assetName: String(data['assetName']),
          assetType: String(data['assetType']),
          assetCategory: String(data['assetCategory']),
          location: String(data['location']),
          managerId: String(data['managerId']),
          photoId: hasPhoto ? String(data['photoAttachmentId']) : null,
          id,
        },
      );
      return { fixedAssetId: Number(id) };
    });
  }

  @Get('/fixed-assets/:fixedAssetId')
  async getFixedAsset(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['fixedAssetId'];
    if (!isId(id)) {
      throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '자산을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT fixed_asset_id AS "fixedAssetId", asset_code AS "assetCode", asset_no AS "assetNo", asset_name AS "assetName", asset_type AS "assetType", asset_category AS "assetCategory", location AS "location", manager_id AS "managerId", photo_attachment_id AS "photoAttachmentId" FROM fixed_asset WHERE fixed_asset_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '자산을 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Post('/asset-changes')
  @HttpCode(200)
  async createAssetChange(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const labels: Record<string, string> = {
      fixedAssetId: '고정자산',
      changeType: '변동 구분',
      changeDate: '변동 일자',
    };
    const missing = Object.keys(labels).filter((k) => blank(data[k]));
    if (missing.length > 0) {
      throw new ApiError(
        422,
        'ASSET_CHANGE_REQUIRED_FIELD_MISSING',
        '필수 입력값이 누락되었습니다: ' + missing.map((k) => labels[k]).join(', '),
      );
    }
    if (!isId(data['fixedAssetId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산 형식이 올바르지 않습니다.');
    }
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(data['changeDate']))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변동 일자는 YYYY-MM-DD 형식이어야 합니다.');
    }
    const content = blank(data['changeContent']) ? null : String(data['changeContent']);
    return transaction(async (db) => {
      const asset = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)',
        { fixedAssetId: String(data['fixedAssetId']) },
      );
      if (asset.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '자산을 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO asset_change (fixed_asset_id, change_type, change_date, change_content, change_status, created_at, updated_at) VALUES (CAST(:fixedAssetId AS bigint), :changeType, CAST(:changeDate AS date), :changeContent, :status, now(), now()) RETURNING asset_change_id AS "assetChangeId"',
        {
          fixedAssetId: String(data['fixedAssetId']),
          changeType: String(data['changeType']),
          changeDate: String(data['changeDate']),
          changeContent: content,
          status: INITIAL_CHANGE_STATUS,
        },
      );
      return rows[0];
    });
  }

  @Get('/asset-changes')
  async listAssetChanges(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const pageNum = blank(q['page']) ? 0 : Number(q['page']);
    const sizeNum = blank(q['size']) ? 20 : Number(q['size']);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeNum, 200);
    const hasFilter = !blank(q['fixedAssetId']);
    if (hasFilter && !isId(q['fixedAssetId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '고정자산 형식이 올바르지 않습니다.');
    }
    const fixedAssetId = hasFilter ? String(q['fixedAssetId']) : null;
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:fixedAssetId AS bigint) IS NULL OR fixed_asset_id = CAST(:fixedAssetId AS bigint))';
      const items = await db.query(
        'SELECT asset_change_id AS "assetChangeId", fixed_asset_id AS "fixedAssetId", change_type AS "changeType", change_date AS "changeDate", change_content AS "changeContent", change_status AS "changeStatus" FROM asset_change ' +
          where +
          ' ORDER BY asset_change_id DESC LIMIT :size OFFSET :offset',
        { fixedAssetId, size, offset: pageNum * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_change ' + where,
        { fixedAssetId },
      );
      return { items, page: pageNum, size, total: Number(counts[0]['total']) };
    });
  }
}

