import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Panel =
  | { kind: 'detail'; id: number }
  | { kind: 'edit'; id: number }
  | { kind: 'newAsset' }
  | { kind: 'newChange'; fixedAssetId?: number }
  | null;

export default function FnSfr02501Page({ role, notify }: PageProps) {
  const [panel, setPanel] = useState<Panel>(null);
  const [assetCode, setAssetCode] = useState('');
  const [assetCodeQ, setAssetCodeQ] = useState('');
  const [assetPage, setAssetPage] = useState(0);
  const [changeAsset, setChangeAsset] = useState<number | string>('');
  const [changeAssetQ, setChangeAssetQ] = useState<number | string>('');
  const [changePage, setChangePage] = useState(0);

  const assets = useData<Page>(
    () => call<Page>('GET', '/fixed-assets', role, undefined, { assetCode: assetCodeQ, page: assetPage, size: 10 }),
    [role, assetCodeQ, assetPage],
  );
  const changes = useData<Page>(
    () => call<Page>('GET', '/asset-changes', role, undefined, { fixedAssetId: changeAssetQ, page: changePage, size: 10 }),
    [role, changeAssetQ, changePage],
  );

  const refresh = () => {
    assets.reload();
    changes.reload();
  };

  return (
    <div className='bento'>
      <section className='box span-6'>
        <h2>자산 수</h2>
        <Tiles items={[['조회된 자산', <Num value={assets.data?.total ?? 0} />]]} />
      </section>
      <section className='box span-6'>
        <h2>변동 건수</h2>
        <Tiles items={[['조회된 변동', <Num value={changes.data?.total ?? 0} />]]} />
      </section>

      <section className='box span-6'>
        <h2>자산정보</h2>
        <Filters
          onSearch={() => {
            setAssetPage(0);
            setAssetCodeQ(assetCode);
          }}
          onReset={() => {
            setAssetCode('');
            setAssetCodeQ('');
            setAssetPage(0);
          }}
        >
          <Field label='자산코드'>
            <TextInput value={assetCode} onChange={setAssetCode} />
          </Field>
        </Filters>
        <Band total={assets.data?.total}>
          <button type='button' onClick={() => setPanel({ kind: 'newAsset' })}>자산 등록</button>
        </Band>
        {assets.error ? <ErrorText text={assets.error} /> : null}
        <DataTable
          rows={assets.data?.items ?? []}
          empty='등록된 자산이 없습니다.'
          onRowClick={(r) => setPanel({ kind: 'detail', id: Number(r['fixedAssetId']) })}
          columns={[
            { key: 'assetCode', label: '자산코드' },
            { key: 'assetNo', label: '자산번호' },
            { key: 'assetName', label: '자산명' },
            { key: 'acquisitionDate', label: '취득일', render: (r) => <DateText value={r['acquisitionDate']} /> },
            { key: 'acquisitionCost', label: '취득원가', render: (r) => <Num value={r['acquisitionCost']} /> },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
          ]}
        />
        <Pager page={assetPage} size={10} total={assets.data?.total ?? 0} onPage={setAssetPage} />
      </section>

      <section className='box span-6'>
        <h2>자산 변동현황</h2>
        <Filters
          onSearch={() => {
            setChangePage(0);
            setChangeAssetQ(changeAsset);
          }}
          onReset={() => {
            setChangeAsset('');
            setChangeAssetQ('');
            setChangePage(0);
          }}
        >
          <Field label='고정자산'>
            <LookupSelect table='fixed_asset' role={role} value={changeAsset} onChange={setChangeAsset} />
          </Field>
        </Filters>
        <Band total={changes.data?.total}>
          <button type='button' onClick={() => setPanel({ kind: 'newChange' })}>변동 등록</button>
        </Band>
        {changes.error ? <ErrorText text={changes.error} /> : null}
        <DataTable
          rows={changes.data?.items ?? []}
          empty='변동 내역이 없습니다.'
          columns={[
            { key: 'fixedAssetId', label: '고정자산', render: (r) => <RefName table='fixed_asset' role={role} value={r['fixedAssetId']} /> },
            { key: 'changeType', label: '변동 구분' },
            { key: 'changeDate', label: '변동 일자', render: (r) => <DateText value={r['changeDate']} /> },
            { key: 'changeContent', label: '변동 내용' },
            { key: 'changeStatus', label: '변동 상태', render: (r) => <Badge value={r['changeStatus']} /> },
          ]}
        />
        <Pager page={changePage} size={10} total={changes.data?.total ?? 0} onPage={setChangePage} />
      </section>

      {panel?.kind === 'detail' ? (
        <Drawer title='자산정보 상세' onClose={() => setPanel(null)}>
          <AssetDetail id={panel.id} role={role} onEdit={() => setPanel({ kind: 'edit', id: panel.id })} onChange={() => setPanel({ kind: 'newChange', fixedAssetId: panel.id })} />
        </Drawer>
      ) : null}
      {panel?.kind === 'edit' ? (
        <Drawer title='자산정보 수정' onClose={() => setPanel(null)}>
          <AssetEdit
            id={panel.id}
            role={role}
            onDone={() => {
              setPanel(null);
              notify('자산정보를 수정했습니다.');
              refresh();
            }}
          />
        </Drawer>
      ) : null}
      {panel?.kind === 'newAsset' ? (
        <Drawer title='자산 등록' onClose={() => setPanel(null)}>
          <AssetCreate
            role={role}
            onDone={() => {
              setPanel(null);
              notify('자산을 등록했습니다.');
              refresh();
            }}
          />
        </Drawer>
      ) : null}
      {panel?.kind === 'newChange' ? (
        <Drawer title='자산 변동 등록' onClose={() => setPanel(null)}>
          <ChangeCreate
            role={role}
            initialAsset={panel.fixedAssetId}
            onDone={() => {
              setPanel(null);
              notify('자산 변동을 등록했습니다.');
              refresh();
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}

function AssetDetail({ id, role, onEdit, onChange }: { id: number; role: string; onEdit: () => void; onChange: () => void }) {
  const d = useData<Row>(() => call<Row>('GET', '/fixed-assets/' + id, role), [id, role]);
  if (d.error) return <ErrorText text={d.error} />;
  const r = d.data;
  if (!r) return <div>불러오는 중…</div>;
  return (
    <div>
      <Pairs
        items={[
          ['자산코드', String(r['assetCode'] ?? '')],
          ['자산번호', String(r['assetNo'] ?? '')],
          ['자산명', String(r['assetName'] ?? '')],
          ['자산 유형', String(r['assetType'] ?? '')],
          ['자산 분류', String(r['assetCategory'] ?? '')],
          ['위치', String(r['location'] ?? '')],
          ['담당자', <RefName table='employee' role={role} value={r['managerId']} />],
          ['자산 사진', r['photoAttachmentId'] ? <RefName table='attachment' role={role} value={r['photoAttachmentId']} /> : '없음'],
        ]}
      />
      <button type='button' onClick={onEdit}>수정</button>
      <button type='button' onClick={onChange}>변동 등록</button>
    </div>
  );
}

function AssetEdit({ id, role, onDone }: { id: number; role: string; onDone: () => void }) {
  const d = useData<Row>(() => call<Row>('GET', '/fixed-assets/' + id, role), [id, role]);
  if (d.error) return <ErrorText text={d.error} />;
  if (!d.data) return <div>불러오는 중…</div>;
  return <AssetEditForm id={id} role={role} init={d.data} onDone={onDone} />;
}

function AssetEditForm({ id, role, init, onDone }: { id: number; role: string; init: Row; onDone: () => void }) {
  const [f, setF] = useState<Row>({ ...init });
  const set = (k: string) => (v: unknown) => setF({ ...f, [k]: v });
  const blank = (v: unknown) => v === undefined || v === null || String(v).trim() === '';
  return (
    <Form
      submit='저장'
      onSubmit={async () => {
        const need: [string, string][] = [
          ['assetCode', '자산코드'],
          ['assetNo', '자산번호'],
          ['assetName', '자산명'],
          ['assetType', '자산 유형'],
          ['assetCategory', '자산 분류'],
          ['location', '위치'],
          ['managerId', '담당자'],
        ];
        const miss = need.filter(([k]) => blank(f[k])).map(([, n]) => n);
        if (miss.length > 0) throw new Error('필수 입력값이 누락되었습니다: ' + miss.join(', '));
        await call('PUT', '/fixed-assets/' + id, role, {
          assetCode: f['assetCode'],
          assetNo: f['assetNo'],
          assetName: f['assetName'],
          assetType: f['assetType'],
          assetCategory: f['assetCategory'],
          location: f['location'],
          managerId: f['managerId'],
          photoAttachmentId: blank(f['photoAttachmentId']) ? undefined : f['photoAttachmentId'],
        });
        onDone();
      }}
    >
      <Field label='자산코드' required><TextInput value={f['assetCode']} onChange={set('assetCode')} /></Field>
      <Field label='자산번호' required><TextInput value={f['assetNo']} onChange={set('assetNo')} /></Field>
      <Field label='자산명' required><TextInput value={f['assetName']} onChange={set('assetName')} /></Field>
      <Field label='자산 유형' required><TextInput value={f['assetType']} onChange={set('assetType')} /></Field>
      <Field label='자산 분류' required><TextInput value={f['assetCategory']} onChange={set('assetCategory')} /></Field>
      <Field label='위치' required><TextInput value={f['location']} onChange={set('location')} /></Field>
      <Field label='담당자' required><LookupSelect table='employee' role={role} value={f['managerId']} onChange={set('managerId')} /></Field>
      <Field label='자산 사진' hint='선택 입력'><LookupSelect table='attachment' role={role} value={f['photoAttachmentId']} onChange={set('photoAttachmentId')} /></Field>
    </Form>
  );
}

function AssetCreate({ role, onDone }: { role: string; onDone: () => void }) {
  const [f, setF] = useState<Row>({ isDepreciable: 'false' });
  const set = (k: string) => (v: unknown) => setF({ ...f, [k]: v });
  const blank = (v: unknown) => v === undefined || v === null || String(v).trim() === '';
  const dep = f['isDepreciable'] === 'true';
  return (
    <Form
      submit='등록'
      onSubmit={async () => {
        const need: [string, string][] = [
          ['assetCode', '자산코드'],
          ['assetNo', '자산번호'],
          ['assetName', '자산명'],
          ['acquisitionDate', '취득일'],
          ['acquisitionCost', '취득원가'],
        ];
        const miss = need.filter(([k]) => blank(f[k])).map(([, n]) => n);
        if (miss.length > 0) throw new Error('필수 입력값이 누락되었습니다: ' + miss.join(', '));
        await call('POST', '/fixed-assets', role, {
          assetCode: f['assetCode'],
          assetNo: f['assetNo'],
          assetName: f['assetName'],
          acquisitionDate: f['acquisitionDate'],
          acquisitionCost: f['acquisitionCost'],
          isDepreciable: dep,
          depreciationMethod: dep && !blank(f['depreciationMethod']) ? f['depreciationMethod'] : undefined,
          usefulLifeYears: dep && !blank(f['usefulLifeYears']) ? f['usefulLifeYears'] : undefined,
          depreciationStartDate: dep && !blank(f['depreciationStartDate']) ? f['depreciationStartDate'] : undefined,
        });
        onDone();
      }}
    >
      <Field label='자산코드' required><TextInput value={f['assetCode']} onChange={set('assetCode')} /></Field>
      <Field label='자산번호' required><TextInput value={f['assetNo']} onChange={set('assetNo')} /></Field>
      <Field label='자산명' required><TextInput value={f['assetName']} onChange={set('assetName')} /></Field>
      <Field label='취득일' required><DateInput value={f['acquisitionDate']} onChange={set('acquisitionDate')} /></Field>
      <Field label='취득원가' required><NumberInput value={f['acquisitionCost']} onChange={set('acquisitionCost')} /></Field>
      <Field label='상각 여부' required>
        <Select value={f['isDepreciable']} onChange={set('isDepreciable')} options={[['true', '예'], ['false', '아니오']]} />
      </Field>
      {dep ? (
        <>
          <Field label='상각 방법'><TextInput value={f['depreciationMethod']} onChange={set('depreciationMethod')} /></Field>
          <Field label='내용연수'><NumberInput value={f['usefulLifeYears']} onChange={set('usefulLifeYears')} /></Field>
          <Field label='상각 시작일'><DateInput value={f['depreciationStartDate']} onChange={set('depreciationStartDate')} /></Field>
        </>
      ) : null}
    </Form>
  );
}

function ChangeCreate({ role, initialAsset, onDone }: { role: string; initialAsset?: number; onDone: () => void }) {
  const [f, setF] = useState<Row>({ fixedAssetId: initialAsset ?? '' });
  const set = (k: string) => (v: unknown) => setF({ ...f, [k]: v });
  const blank = (v: unknown) => v === undefined || v === null || String(v).trim() === '';
  return (
    <Form
      submit='등록'
      onSubmit={async () => {
        const need: [string, string][] = [
          ['fixedAssetId', '고정자산'],
          ['changeType', '변동 구분'],
          ['changeDate', '변동 일자'],
        ];
        const miss = need.filter(([k]) => blank(f[k])).map(([, n]) => n);
        if (miss.length > 0) throw new Error('필수 입력값이 누락되었습니다: ' + miss.join(', '));
        await call('POST', '/asset-changes', role, {
          fixedAssetId: f['fixedAssetId'],
          changeType: f['changeType'],
          changeDate: f['changeDate'],
          changeContent: blank(f['changeContent']) ? undefined : f['changeContent'],
        });
        onDone();
      }}
    >
      <Field label='고정자산' required><LookupSelect table='fixed_asset' role={role} value={f['fixedAssetId']} onChange={set('fixedAssetId')} /></Field>
      <Field label='변동 구분' required><TextInput value={f['changeType']} onChange={set('changeType')} /></Field>
      <Field label='변동 일자' required><DateInput value={f['changeDate']} onChange={set('changeDate')} /></Field>
      <Field label='변동 내용' wide><TextInput multiline value={f['changeContent']} onChange={set('changeContent')} /></Field>
    </Form>
  );
}
